import{_ as t,o as i,c as n,a5 as a}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"BrandHub Mobile App — Design & Phasing Plan","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/mobile-app-plan.md","filePath":"mobile/mobile-app-plan.md"}'),o={name:"mobile/mobile-app-plan.md"};function c(h,e,r,l,d,g){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="brandhub-mobile-app-—-design-phasing-plan" tabindex="-1">BrandHub Mobile App — Design &amp; Phasing Plan <a class="header-anchor" href="#brandhub-mobile-app-—-design-phasing-plan" aria-label="Permalink to &quot;BrandHub Mobile App — Design &amp; Phasing Plan&quot;">​</a></h1><p>&gt; Trạng thái: DRAFT — chờ xác nhận trước khi bắt đầu implementation. &gt; Phạm vi: mở rộng <code>brandhub-mobile-app</code> (Expo/React Native) từ &quot;approval + notification only&quot; thành bản thu nhỏ đầy đủ của web, cộng thêm tính năng mới Creator Upload. &gt; Đây KHÔNG phải FR chính thức trong SRS (125 FR) — coi là hạng mục kỹ thuật bổ sung, không sửa <code>docs/ba/</code> hay <code>docs/plan/document-plan.md</code>.</p><h2 id="_1-boi-canh-quyet-đinh-đa-chot" tabindex="-1">1. Bối cảnh &amp; quyết định đã chốt <a class="header-anchor" href="#_1-boi-canh-quyet-đinh-đa-chot" aria-label="Permalink to &quot;1. Bối cảnh &amp; quyết định đã chốt&quot;">​</a></h2><ul><li><strong>Stack:</strong> giữ Expo (managed) + React Native đã scaffold trong <code>brandhub-mobile-app</code> — không đổi sang PWA/Safari, không eject bare RN ở các giai đoạn đầu. <ul><li>Lý do: PWA trên iOS Safari không hỗ trợ background upload/sync bền (WebKit limitation), push notification yếu. Expo RN không bị giới hạn cứng này, chỉ hạn chế hơn bare RN cho background task — có thể nâng cấp sau (prebuild + native module) mà không cần đổi stack.</li></ul></li><li><strong>Background upload:</strong> giai đoạn đầu KHÔNG làm app chạy nền khi bị kill/minimize. Upload chạy khi app đang mở (foreground). Nếu cần background thật (iOS <code>URLSession background transfer</code>, Android <code>WorkManager</code>), đó là nâng cấp sau, cần Expo prebuild + native module riêng.</li><li><strong>Demo/build:</strong> không cần App Store public release. Dùng Expo Go cho demo nhanh, hoặc EAS Build + TestFlight/ad-hoc nếu cần test native module thật trên thiết bị. Cần xác nhận team đã có Apple Developer account hay chưa trước khi tới giai đoạn cần build thật.</li><li><strong>Mục tiêu cuối:</strong> mobile app là bản thu nhỏ đầy đủ của web — user dùng mobile thay web được cho hầu hết tác vụ chính, cộng thêm tính năng Creator Upload (không có bên web).</li><li><strong>Thứ tự triển khai:</strong> Auth đầy đủ → Creator Upload (điểm nhấn kỹ thuật mới) → các domain còn lại của web (Agency/Workspace, Package/Campaign, Task, AI Features, Subscription/Billing).</li></ul><h2 id="_2-creator-upload-—-mo-ta-tinh-nang-moi-điem-nhan" tabindex="-1">2. Creator Upload — mô tả tính năng mới (điểm nhấn) <a class="header-anchor" href="#_2-creator-upload-—-mo-ta-tinh-nang-moi-điem-nhan" aria-label="Permalink to &quot;2. Creator Upload — mô tả tính năng mới (điểm nhấn)&quot;">​</a></h2><p>Pain point gốc: nhà sáng tạo nội dung quay xong clip tại hiện trường (sự kiện, livestream BTS...), cần đưa file vào hệ thống nhanh, không phải mang máy về mở web upload.</p><p><strong>Giai đoạn 1 (MVP):</strong></p><ol><li>Creator mở app, thấy list Task được Manager giao sẵn (không tự tạo Task mới ở bước này).</li><li>Chọn 1 Task → trong Task Detail có nút: quay video trong app (camera native) <strong>hoặc</strong> chọn file có sẵn từ thư viện máy.</li><li>App xin presigned PUT URL từ <code>brandhub-business-service</code> (theo pattern <code>S3FileStorageService</code>/<code>UploadS3Controller</code> đã có), PUT file thẳng lên S3 — không qua server trung gian.</li><li>Có progress bar; hỗ trợ retry/resume khi mất mạng giữa chừng (video raw thường vài trăm MB, mạng di động không ổn định).</li><li>Upload xong → gắn file vào Task đó, lưu vào Material Repository với phân loại <strong>raw</strong> (đúng field raw/retouched đã có ở FR 3.6.11–3.6.14).</li><li><strong>Dừng ở đây.</strong> Chưa làm AI auto-edit, chưa auto-caption, chưa auto-tạo Task mới.</li></ol><p><strong>Giai đoạn 2 (sau, chưa thiết kế chi tiết — placeholder):</strong></p><ul><li>AI xử lý raw footage (cắt short, chọn đoạn đẹp, auto-caption) — cần làm rõ: dùng tool edit video thật (ví dụ ffmpeg-based service) vì <code>AiVideoService</code>/Veo hiện tại là <em>generate</em> video từ prompt, không phải <em>edit</em> video có sẵn — đây là năng lực kỹ thuật MỚI, chưa tồn tại trong <code>brandhub-ai-service</code>.</li><li>Khi AI xong, tạo Task mới ở trạng thái <code>IN_REVIEW</code> / MANAGER theo Approval Sequence đã có (FR 3.6.9), không bỏ qua approval, không tự publish.</li><li>Chi tiết đầy đủ giai đoạn 2 sẽ viết thành doc riêng sau khi giai đoạn 1 chạy ổn và biết rõ năng lực AI edit thật có khả thi trong thời gian còn lại của capstone không.</li></ul><h3 id="điem-cham-he-thong-hien-co-đa-đoc-code-khong-đoan" tabindex="-1">Điểm chạm hệ thống hiện có (đã đọc code, không đoán) <a class="header-anchor" href="#điem-cham-he-thong-hien-co-đa-đoc-code-khong-đoan" aria-label="Permalink to &quot;Điểm chạm hệ thống hiện có (đã đọc code, không đoán)&quot;">​</a></h3><ul><li><code>brandhub-business-service/.../controller/UploadS3Controller.java</code> — mẫu test endpoint upload hiện tại, cần thiết kế lại thành endpoint chính thức cấp presigned URL + xác nhận gắn Task/Material.</li><li><code>brandhub-business-service/.../service/FileStorageService.java</code> + <code>S3FileStorageServiceImpl.java</code> — nền tảng S3 có sẵn.</li><li><code>brandhub-business-service/.../document/MaterialDocument.java</code> — Material Repository entity, cần xác nhận field raw/retouched map đúng với yêu cầu mobile.</li><li><code>brandhub-business-service/.../service/ai/AiVideoService.java</code> — AI video generate (Veo) có sẵn, KHÔNG dùng được cho &quot;edit raw footage&quot; ở giai đoạn 2 mà không viết thêm service mới.</li><li><code>brandhub-ai-service/app/services/caption_service.py</code> — có sẵn, dùng được cho auto-caption ở giai đoạn 2.</li></ul><h2 id="_3-cac-giai-đoan-tong-the" tabindex="-1">3. Các giai đoạn tổng thể <a class="header-anchor" href="#_3-cac-giai-đoan-tong-the" aria-label="Permalink to &quot;3. Các giai đoạn tổng thể&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Giai đoạn</th><th>Nội dung</th><th>Ghi chú</th></tr></thead><tbody><tr><td>G0</td><td>Viết design doc + xác nhận scope (đang làm)</td><td>File này + các file con bên dưới</td></tr><tr><td>G1</td><td>Auth đầy đủ: Sign In Email, Sign In Google OAuth, Forgot/Reset Password</td><td>Khớp FR 3.2.1–3.2.9, tái dùng <code>expo-secure-store</code> đã có</td></tr><tr><td>G2</td><td>Creator Upload giai đoạn 1 (mô tả mục 2)</td><td>Điểm nhấn kỹ thuật mới của đồ án</td></tr><tr><td>G3</td><td>Agency/Workspace: list/view Agency, Workspace, invite member</td><td></td></tr><tr><td>G4</td><td>Media Package/Campaign: xem + approve (Owner/Client)</td><td></td></tr><tr><td>G5</td><td>Task management đầy đủ: list/kanban/calendar/detail/comment (không chỉ approval queue như hiện tại)</td><td></td></tr><tr><td>G6</td><td>AI Features: generate caption/image/video từ mobile, xem credit</td><td></td></tr><tr><td>G7</td><td>Subscription/Billing: xem/mua plan, invoice history</td><td></td></tr><tr><td>G8 (sau)</td><td>Creator Upload giai đoạn 2: AI edit raw + auto-caption + auto-queue Task IN_REVIEW</td><td>Chưa thiết kế chi tiết, phụ thuộc khả năng AI edit thật</td></tr></tbody></table><p>Mỗi giai đoạn G1–G7 có 1 folder riêng trong <code>docs/mobile/features/&lt;giai-đoạn&gt;/spec.md</code> (feature spec đầy đủ: mục tiêu, FR tham chiếu, API thật đọc từ code, luồng màn hình, state/cache, business rule, non-goal, rủi ro/câu hỏi mở). Đã viết xong cả 7 file, dựa trên đọc code thật (business-service, mobile-app, web) — không đoán. Danh sách:</p><ul><li><a href="./features/g1-auth/spec.html"><code>features/g1-auth/spec.md</code></a></li><li><a href="./features/g2-creator-upload/spec.html"><code>features/g2-creator-upload/spec.md</code></a></li><li><a href="./features/g3-agency-workspace/spec.html"><code>features/g3-agency-workspace/spec.md</code></a></li><li><a href="./features/g4-package-campaign/spec.html"><code>features/g4-package-campaign/spec.md</code></a></li><li><a href="./features/g5-task-management/spec.html"><code>features/g5-task-management/spec.md</code></a></li><li><a href="./features/g6-ai-features/spec.html"><code>features/g6-ai-features/spec.md</code></a></li><li><a href="./features/g7-subscription-billing/spec.html"><code>features/g7-subscription-billing/spec.md</code></a></li></ul><p><strong>Phát hiện quan trọng từ việc đọc code thật (cần team xác nhận, xem mục &quot;Rủi ro/câu hỏi mở&quot; mỗi file để chi tiết):</strong></p><ul><li>G1: Google OAuth flow backend hiện tại đã bị BA đánh dấu &quot;chưa chạy được&quot;; refresh token dùng HttpOnly cookie, mobile không có — cần BE đổi flow.</li><li>G2: presigned PUT upload chưa tồn tại (chỉ có presigned GET); Material chưa có field <code>taskId</code> — đều là việc mới cần thêm ở backend.</li><li>G3: role thật per-Workspace chỉ có OWNER/MANAGER/CREATOR/CLIENT (không có ADMIN/GUEST ở cấp này — khác giả định ban đầu).</li><li>G4: approve Campaign KHÔNG tự đẩy Task vào backlog — có bước <code>/deploy</code> riêng, khác với mô tả trong BA doc 04.</li><li>G5: tồn tại 2 model Task (SQL rỗng vs MongoDB thật) — phải build theo MongoDB; đề xuất bỏ Gantt view và content-editor khỏi scope mobile (chưa được xác nhận).</li><li>G7: cổng thanh toán thật là SePay (QR chuyển khoản), không phải PayOS như BA doc ghi; đề xuất mobile chỉ xem plan/invoice, hành động mua/upgrade mở browser ngoài (an toàn chính sách IAP) — đề xuất của tôi, chưa được xác nhận.</li></ul><h2 id="_4-viec-can-lam-tiep-khong-code" tabindex="-1">4. Việc cần làm tiếp (không code) <a class="header-anchor" href="#_4-viec-can-lam-tiep-khong-code" aria-label="Permalink to &quot;4. Việc cần làm tiếp (không code)&quot;">​</a></h2><ol><li>Xác nhận file plan này đúng ý trước khi viết chi tiết G1.</li><li>Viết <code>docs/mobile/g1-auth.md</code> — chi tiết hoá Auth đầy đủ trên mobile.</li><li>Viết <code>docs/mobile/g2-creator-upload.md</code> — chi tiết hoá Creator Upload giai đoạn 1 (API cần thêm ở business-service, UI flow, error case).</li><li>Sau khi G1+G2 doc được duyệt, mới chuyển qua <code>superpowers:writing-plans</code> để lên implementation plan thật (bước code).</li></ol><h2 id="_5-rui-ro-đa-biet" tabindex="-1">5. Rủi ro đã biết <a class="header-anchor" href="#_5-rui-ro-đa-biet" aria-label="Permalink to &quot;5. Rủi ro đã biết&quot;">​</a></h2><ul><li>Apple Developer account: chưa xác nhận team đã có — cần thiết nếu muốn test build thật qua TestFlight/EAS (không cần cho Expo Go demo).</li><li>AI edit raw footage (giai đoạn 2) là năng lực mới, không có sẵn trong <code>brandhub-ai-service</code> — cần đánh giá effort riêng trước khi cam kết đưa vào giai đoạn 2.</li><li>Scope mobile mở rộng toàn bộ web là effort lớn cho capstone — cần theo dõi tiến độ G3–G7 so với deadline cuối tháng 11/2026, có thể phải cắt bớt nếu không kịp.</li></ul>',22)])])}const u=t(o,[["render",c]]);export{p as __pageData,u as default};
